    30→func TestMessageEncodeDecodeRoundtrip(t *testing.T) {
    31→	msg := Message{
    32→		Version: ProtoVersion,
    33→		Type:    MsgRequest,
    34→		ID:      12345,
    35→		Method:  []byte("TestMethod"),
    36→		Body:    []byte("test body content"),
    37→	}
    38→
    39→	// Encode.
    40→	encoded := msg.Encode(nil)
    41→
    42→	// Decode header.
    43→	var decoded Message
    44→	methodLen, errorLen, bodyLen, err := DecodeHeader(encoded[:HeaderSize], &decoded)
    45→	if err != nil {
    46→		t.Fatalf("DecodeHeader error: %v", err)
    47→	}
    48→
    49→	// Decode body.
    50→	payload := encoded[HeaderSize:]
    51→	DecodeBody(payload, &decoded, methodLen, errorLen, bodyLen)
    52→
    53→	// Verify.
    54→	if decoded.Version != ProtoVersion || decoded.Type != MsgRequest || decoded.ID != 12345 {
    55→		t.Errorf("Header mismatch: %+v", decoded)
    56→	}
    57→
    58→	if string(decoded.Method) != "TestMethod" {
    59→		t.Errorf("Method mismatch: %q", string(decoded.Method))
    60→	}
    61→
    62→	if string(decoded.Body) != "test body content" {
