     9→// KVStoreHandler wraps a *kvstore.Cluster and exposes its operations as RPC methods.
    10→type KVStoreHandler struct {
    11→	cluster *kvstore.Cluster
    12→	codec   Codec
    13→}
    14→
    15→// NewKVStoreHandler creates a handler wrapping cluster.
    16→func NewKVStoreHandler(cluster *kvstore.Cluster, codec Codec) *KVStoreHandler {
    17→	return &KVStoreHandler{
    18→		cluster: cluster,
    19→		codec:   codec,
    20→	}
    21→}
    22→
    23→// Register installs Set, Get, Delete, Stats on server.
    24→// Method names: "KV.Set", "KV.Get", "KV.Delete", "KV.Stats"
    25→func (h *KVStoreHandler) Register(s *Server) error {
    26→	if err := s.Register("KV.Set", h.handleSet); err != nil {
    27→		return err
    28→	}
    29→	if err := s.Register("KV.Get", h.handleGet); err != nil {
    30→		return err
    31→	}
    32→	if err := s.Register("KV.Delete", h.handleDelete); err != nil {
    33→		return err
    34→	}
    35→	if err := s.Register("KV.Stats", h.handleStats); err != nil {
    36→		return err
    37→	}
    38→	return nil
    39→}
