    41→// handleSet handles KV.Set: args are {key, value} (both strings).
    42→func (h *KVStoreHandler) handleSet(args []byte) ([]byte, error) {
    43→	var key string
    44→	var value string
    45→
    46→	// Decode key.
    47→	keyBuf := make([]byte, len(args))
    48→	copy(keyBuf, args)
    49→	if err := h.codec.Unmarshal(keyBuf, &key); err != nil {
    50→		return nil, fmt.Errorf("unmarshal key: %w", err)
    51→	}
    52→
    53→	// Find where value starts (after key encoding).
    54→	codec := NewBinaryCodec() // to skip key in buffer
    55→	keyEncoded, _ := codec.Marshal(key, make([]byte, 0))
    56→	if len(args) <= len(keyEncoded) {
    57→		return nil, fmt.Errorf("missing value in args")
    58→	}
    59→
    60→	valueBuf := args[len(keyEncoded):]
    61→	if err := h.codec.Unmarshal(valueBuf, &value); err != nil {
    62→		return nil, fmt.Errorf("unmarshal value: %w", err)
    63→	}
    64→
    65→	// Call cluster.Set.
    66→	if err := h.cluster.Set(key, value); err != nil {
    67→		return nil, err
    68→	}
    69→
    70→	// Return nil result.
    71→	return h.codec.Marshal(nil, make([]byte, 0))
    72→}
    73→
    74→// handleGet handles KV.Get: args is a string (key), result is a string (value).
    75→func (h *KVStoreHandler) handleGet(args []byte) ([]byte, error) {
    76→	var key string
    77→	if err := h.codec.Unmarshal(args, &key); err != nil {
    78→		return nil, fmt.Errorf("unmarshal key: %w", err)
    79→	}
    80→
    81→	// Call cluster.Get.
    82→	value, err := h.cluster.Get(key)
    83→	if err != nil {
    84→		return nil, err
    85→	}
    86→
    87→	// Marshal result.
    88→	return h.codec.Marshal(value, make([]byte, 0))
    89→}
