    91→// handleDelete handles KV.Delete: args is a string (key), result is a bool.
    92→func (h *KVStoreHandler) handleDelete(args []byte) ([]byte, error) {
    93→	var key string
    94→	if err := h.codec.Unmarshal(args, &key); err != nil {
    95→		return nil, fmt.Errorf("unmarshal key: %w", err)
    96→	}
    97→
    98→	// Call cluster.Delete.
    99→	err := h.cluster.Delete(key)
   100→	success := err == nil
   101→
   102→	// Marshal result (true if deleted, false otherwise).
   103→	return h.codec.Marshal(success, make([]byte, 0))
