   106→// handleStats handles KV.Stats: no args, result is a struct with counts.
   107→func (h *KVStoreHandler) handleStats(args []byte) ([]byte, error) {
   108→	stats := h.cluster.Stats()
   109→
   110→	// Marshal as four int64 values: TotalNodes, AliveNodes, DeadNodes, TotalKeys.
   111→	result := make([]byte, 0, 256)
